function stairs(steps: number) {
    for (let index = 0; index < steps; index++) {
        agent.move(SixDirection.Up, 1)
        agent.move(SixDirection.Forward, 1)
        agent.place(SixDirection.Down)
    }
}

agent.setItem(Block.Stone, 64, 1)
stairs(2)
